        new(query.SubtotalCents, 0, query.SubtotalCents, query.LoyaltyTier);""","""    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discountCents = LoyaltyDiscountPolicy.DiscountCents(query.SubtotalCents, query.LoyaltyTier);
        return new(query.SubtotalCents, discountCents, query.SubtotalCents - discountCents, query.LoyaltyTier);
    }""")
open(p,'w').write(s)
EOF
